function invoiceTotal(unitPriceCents, quantity, taxPercent) {
  const subtotal = unitPriceCents * quantity;
  const tax = Math.round(subtotal * taxPercent / 100);
  return subtotal + tax;
}
console.log(invoiceTotal(1999, 3, 10));
